"""Synthetic DOM regression test, not a Windows runtime test. Requires Python Playwright and Chromium for tests only."""
from pathlib import Path
import json, html, os
from playwright.sync_api import sync_playwright
P=Path(__file__).resolve().parent
D=json.loads((P/'translations.json').read_text());script=(P/'localize.js').read_text().replace('__DICT__',json.dumps(D,ensure_ascii=False));script=script.replace("location.protocol === 'https:' && location.hostname === '127.0.0.1' && window.top === window",'true')
assert len(D)==567
labels=['Permissions','Configure what the agent can do in local and remote conversations.','This computer','Controls permissions for remote conversations.','Advanced','Modify permissions for file and terminal tools.','Chat Layout','Conversation width','Configure the maximum width of the conversation panel.','Narrow','Wide','Fill','Accessibility','Screen reader mode','Optimize the interface and terminal output for screen readers.','Browser Actuation Permissions','Execute URLs','Allow/deny agent browser actuation access to specific URLs.','Download files','Allow/deny agent browser file downloads from specific sites.','Please describe the issue in detail. The more actionable your feedback, the quicker our team can address your request. Some helpful information includes:','Steps to reproduce the issue','Expected behavior','Actual behavior','Any error messages','Any relevant information','Steps to Reproduce','Attach a screenshot (optional)','Attach Antigravity server logs','Submit','Visit','Legal Help','to ask for content changes for legal reasons.','Manage your plan, credentials, and general preferences.','Enable telemetry','When toggled on, Antigravity collects usage data to help Google enhance performance and features.','Marketing emails','Receive product updates, tips, and promotions from Google Antigravity via email.','Email','Remote Agents Data','Delete all Remote Agents data','Permanently delete your remote conversations, projects, scheduled tasks, connected plugins and settings. Data in the desktop app and your Google account are not affected.','Delete All Data','By using this app, you agree to its','Terms of Service']
profiles=['Request Review','Every command requires approval.','Default','Ask before sensitive operations.','Auto','Automatically decide if commands run.','Turbo','Run all commands without restrictions.']
keys=['Open Conversation Picker','Open File Search','Open Command Palette','Toggle Sidebar','Mute Voice Mic','Select Next Conversation','Download Diagnostics']
empty="Run a prompt on a schedule, like a morning summary of yesterday's changes. Runs show up here."
markup='''<html><body><nav><button>Workspace</button><button>Automations</button></nav><div id=workspace><span>New Conversation</span><span>Create Project</span><span>Command Palette</span></div><main id=auto><header><h1>Automations</h1><button>Create with Prompt</button><button>New</button></header><section><h2>No automations yet</h2><p>'''+html.escape(empty)+'''</p></section></main><article id=chat>Delete All Data</article><div role=alert id=warning>Run all commands without restrictions.</div><div role=dialog id=prefs><aside><div>Settings</div><div>General</div><div>Application</div><div>Appearance</div><div>Shortcuts</div><div>Notifications</div></aside><section>'''+''.join(f'<div id=l{i}>{html.escape(k)}</div>' for i,k in enumerate(labels))+'''<input id=ss placeholder="Search shortcuts..."><div id=shortrows></div><textarea id=feedback placeholder="Describe the bug you encountered...">Do not translate me</textarea><textarea id=steps placeholder="Please list the steps to reproduce the issue"></textarea><p id=send>Send feedback as user@example.invalid</p><p id=quota>You have used some of your weekly limit, it will fully refresh in 6 days, 23 hours.</p><div role=alertdialog id=confirm>Delete All Data</div></section></div><div role=listbox id=portal>'''+''.join(f'<div role=option id=p{i}><span>{html.escape(k)}</span></div>' for i,k in enumerate(profiles))+'''</div><div role=dialog id=palette><button>Commands</button><input id=search placeholder="Search for commands..."><div role=listbox id=results></div></div></body></html>'''
with sync_playwright() as pw:
 browser=pw.chromium.launch(executable_path=os.getenv('CHROMIUM','/usr/bin/chromium'),headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1200,'height':1000});page.set_content(markup)
 page.evaluate('''keys=>{window.executions=0;const add=(inputId,outId)=>{const inp=document.getElementById(inputId),r=document.getElementById(outId);const render=q=>{r.replaceChildren();keys.filter(k=>k.toLowerCase().includes(q.toLowerCase())).forEach(k=>{let row=document.createElement('div');row.setAttribute('role','option');let span=document.createElement('span');span.textContent=k;row.append(span);let key=document.createElement('kbd');key.textContent='Ctrl+K';row.append(key);row.onclick=()=>window.executions++;r.append(row)})};inp.addEventListener('input',e=>render(e.target.value));render('')};add('search','results');add('ss','shortrows')}''',keys[:-1])
 page.evaluate(script);page.wait_for_timeout(250)
 for i,k in enumerate(labels):assert page.locator(f'#l{i}').text_content()==D[k],(k,page.locator(f'#l{i}').text_content())
 for i,k in enumerate(profiles):assert page.locator(f'#p{i} span').text_content()==D[k],(k,page.locator(f'#p{i} span').text_content())
 assert page.locator('#chat').text_content()=='Delete All Data';assert page.locator('#confirm').text_content()=='Delete All Data';assert page.locator('#warning').text_content()==profiles[-1]
 assert page.locator('#feedback').get_attribute('placeholder')==D['Describe the bug you encountered...'];assert page.locator('#feedback').input_value()=='Do not translate me';assert page.locator('#steps').get_attribute('placeholder')==D['Please list the steps to reproduce the issue']
 assert page.locator('#send').text_content()=='Отправить отзыв от имени user@example.invalid';assert page.locator('#quota').text_content()=='Часть недельного лимита использована. Он полностью обновится через 6 дней, 23 часа.'
 for target in ['shortrows','results']:
  for k in keys[:-1]:
   el=page.locator(f'#{target} span').filter(has_text=k).first;assert el.text_content()==k;assert el.get_attribute('data-ag-ru-command-label')==D[k],(target,k,el.get_attribute('data-ag-ru-command-label'))
  assert all(x=='Ctrl+K' for x in page.locator(f'#{target} kbd').all_text_contents())
 for inp,target in [('ss','shortrows'),('search','results')]:
  page.locator('#'+inp).fill('Open File Search');page.wait_for_timeout(150);assert page.locator('#'+target+' span').all_text_contents()==['Open File Search']
  page.locator('#'+inp).fill('поиск файл');page.wait_for_timeout(150);helper=page.locator('[data-ag-ru-search-helper]');assert helper.count()==1;btn=helper.locator('button').filter(has_text='Open File Search');assert btn.count()==1;btn.evaluate('b=>b.click()');page.wait_for_timeout(150);assert page.locator('#'+inp).input_value()=='Open File Search';assert page.locator('#'+target+' span').all_text_contents()==['Open File Search'];assert page.evaluate('window.executions')==0
  page.locator('#'+inp).fill('');page.wait_for_timeout(150);assert page.locator('[data-ag-ru-search-helper]').count()==0
 assert page.locator('#auto h2').text_content()==D['No automations yet'];assert page.locator('#workspace span').all_text_contents()==[D[k] for k in ['New Conversation','Create Project','Command Palette']]
 browser.close()
print('PASS: settings labels, profile portal, placeholders, data unchanged, native and RU shortcut/command search, no auto-execution, legacy page and quota')
